/** State slug -> postal abbreviation for bulk city labels. */
const ABBR: Record<string, string> = { "alabama": "AL", "alaska": "AK", "arizona": "AZ", "arkansas": "AR", "california": "CA", "colorado": "CO", "connecticut": "CT", "delaware": "DE", "district-of-columbia": "DC", "florida": "FL", "georgia": "GA", "hawaii": "HI", "idaho": "ID", "illinois": "IL", "indiana": "IN", "iowa": "IA", "kansas": "KS", "kentucky": "KY", "louisiana": "LA", "maine": "ME", "maryland": "MD", "massachusetts": "MA", "michigan": "MI", "minnesota": "MN", "mississippi": "MS", "missouri": "MO", "montana": "MT", "nebraska": "NE", "nevada": "NV", "new-hampshire": "NH", "new-jersey": "NJ", "new-mexico": "NM", "new-york": "NY", "north-carolina": "NC", "north-dakota": "ND", "ohio": "OH", "oklahoma": "OK", "oregon": "OR", "pennsylvania": "PA", "rhode-island": "RI", "south-carolina": "SC", "south-dakota": "SD", "tennessee": "TN", "texas": "TX", "utah": "UT", "vermont": "VT", "virginia": "VA", "washington": "WA", "west-virginia": "WV", "wisconsin": "WI", "wyoming": "WY" };

/** "City Name, ST" label for bulk cities. */
export function bulkLabel(c: Pick<City, "slug" | "stateSlug">): string {
  const name = c.slug
    .split("-")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ")
    .replace(/\s[A-Z]{2}$/, "");
  const abbr = ABBR[c.stateSlug] ?? "";
  return abbr ? `${name}, ${abbr}` : name;
}

/** True when the slug belongs to the programmatic set. */
const bulkSlugs = new Set(bulkCities.map((c) => c.slug + "|" + c.stateSlug));
export function isBulkCity(stateSlug: string, slug: string): boolean {
  return bulkSlugs.has(slug + "|" + stateSlug);
}
